"""Numbers only: C of a sheet, what a sheet is worth to the supplier, the non-price terms we ask for
and, in relationship goals, the price below which a lower price costs us more than it saves.
Nothing here calls a model; every figure that reaches a term sheet comes from here."""

import itertools
import math

from arena_kit.cost import closing_terms, complete_offer, must_haves_ok, supplier_value, total_cost

RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}


def cost(case, terms, std=None, est=None):
    """C in EUR; infinite for sheets the cost function cannot price. The relationship charge
    needs a full-cost estimate; without one it counts as 0."""
    if est is not None and not est.get("full_cost"):
        est = None
    try:
        return total_cost(case, terms, std, est)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        return math.inf


def c_alt(case):
    alt = case["buyer"].get("alternative") or {}
    terms = alt.get("terms") or {}
    if alt.get("kind") in (None, "none") or not terms.get("unit_price"):
        return math.inf
    return cost(case, terms)


def deal_cost(case, terms, std, est=None):
    """The accept gate: C of a sheet with a price that keeps every must-have and is cheaper than
    the alternative (relationship charge included), else None. The C returned is the C checked."""
    if not terms.get("unit_price") or not must_haves_ok(case, terms, std):
        return None
    c = cost(case, terms, std, est)
    return c if c < c_alt(case) else None


def known_incoterm(case, terms):
    """`terms` with an Incoterm the case prices; an unknown one (a hidden case's quote) would be a
    KeyError in the kit, so it falls back to the costliest, as `closing_terms` does for a gap."""
    freight = case["buyer"]["freight_eur_per_unit"]
    if terms.get("incoterm") in freight or "incoterm" not in terms:
        return terms
    return {**terms, "incoterm": max(freight, key=freight.get)}


def estimate(case, std, rate, full_cost=None, ppm=None, lead=None, overtime=0.0):
    """Our view of the supplier for `supplier_value` and the relationship term. `lead`: the lead
    time it quoted; `overtime`: what each day faster costs it, as a share of the price."""
    standard = known_incoterm(case, closing_terms(case, {}, known_incoterm(case, std or {})))
    est = {"standard": standard, "interest_rate": rate, "lead": lead, "overtime": overtime}
    if ppm is not None:
        est["ppm"] = ppm
    if full_cost:
        est["full_cost"] = full_cost
    est["index_moves"] = {}  # series -> its change over the last 12 months (share), what the supplier expects on
    return est


def clause_value(case, terms, est):
    """What an index clause is worth to the supplier per unit: it expects its driver to move on as
    it did over the last twelve months (what it cites in its quote), and the clause pays it that
    share beyond the deadband. Nordmark agreed at once to a copper clause 4 % below its fixed
    price (P02); the distributors priced the AS-14404 deadband at exactly this (P08, P18)."""
    clause = terms.get("index_clause")
    if not clause:
        return 0.0
    move = est.get("index_moves", {}).get(clause.get("series"))
    if move is None:
        return 0.0
    exposed = max(0.0, move - (clause.get("deadband_pct") or 0) / 100)
    return (clause.get("material_share") or 0) * exposed * (terms.get("unit_price") or 0)


def clause_cost_share(case, clause):
    """Our cost of a clause as a share of the spend: the case's path beyond the deadband plus the
    index risk charge."""
    b = case["buyer"]
    share, deadband = clause.get("material_share") or 0, (clause.get("deadband_pct") or 0) / 100
    path = abs(b.get("index_paths", {}).get(clause.get("series"), 0.0))
    return share * max(0.0, path - deadband) + share * b.get("index_risk_pct", 0) / 100


def clause_trade(case, est, min_gain=0.02):
    """The index clause worth trading: the supplier's value less our cost, as a share of the price,
    above `min_gain`; among equal gains the widest deadband (least risk). None when no clause pays
    (P08, P18: the supplier's value equals our cost) or the case has none to offer."""
    best = None
    for clause in case.get("term_options", {}).get("index_clause") or []:
        if not clause:
            continue
        move = est.get("index_moves", {}).get(clause.get("series"))
        if move is None:
            continue
        theirs = (clause.get("material_share") or 0) * max(0.0, move - (clause.get("deadband_pct") or 0) / 100)
        gain = theirs - clause_cost_share(case, clause)
        key = (round(gain, 4), clause.get("deadband_pct") or 0)
        if gain >= min_gain and (best is None or key > best[0]):
            best = (key, clause)
    return best[1] if best else None


def value(case, terms, est):
    """What a sheet is worth to the supplier per unit, in cash at its standard terms, less the
    overtime a faster delivery than it quoted costs it (fully booked suppliers: about 0.5 % of
    the price per day, P05 and P10)."""
    v = supplier_value(case, known_incoterm(case, terms), est) + clause_value(case, terms, est)
    lead, quoted = terms.get("lead_time_days"), est.get("lead")
    if est.get("overtime") and lead is not None and quoted and lead < quoted:
        v -= est["overtime"] * terms["unit_price"] * (quoted - lead)
    return v


def price_for_value(case, terms, est, target):
    """The unit price at which `terms` are worth `target` to the supplier (value rises with price)."""
    lo, hi = 0.0, max(1.0, target) * 3
    for _ in range(60):
        mid = (lo + hi) / 2
        if value(case, {**terms, "unit_price": mid}, est) < target:
            lo = mid
        else:
            hi = mid
    return hi


def options(case):
    """Every combination of allowed non-price values: [{field: value}]."""
    opts = case.get("term_options") or {}
    fields = [f for f in case["negotiable"] if f != "unit_price" and opts.get(f)]
    return [dict(zip(fields, combo, strict=True)) for combo in itertools.product(*(opts[f] for f in fields))]


# Where a value costs us nothing more, the side the supplier prefers: a later delivery needs no
# overtime, a longer contract and a larger volume give it security (months beyond our horizon
# cost us nothing), a looser defect commitment and a smaller chargeback cost it less.
FRIENDLY = {
    "lead_time_days": 1,
    "contract_months": 1,
    "volume_per_year": 1,
    "ppm_commitment": 1,
    "chargeback_eur_per_complaint": -1,
    "tooling_eur": 1,
}


def friendliness(terms):
    """Higher is better for the supplier."""
    return tuple(FRIENDLY[f] * (terms.get(f) or 0) for f in FRIENDLY if f in terms)


def plan_terms(case, std, est, ref_terms, ref_price):
    """The non-price terms that cost us least once the supplier prices them at its own valuation:
    for every allowed combination, the price worth the same to it as `ref_price` at `ref_terms`,
    then C at that price; among equal C, the supplier's favourite. Returns (terms with that price, C)."""
    target = value(case, {**ref_terms, "unit_price": ref_price}, est)
    rows = []
    for combo in options(case) or [{}]:
        terms = complete_offer(case, {**ref_terms, **combo, "unit_price": ref_price})
        terms["unit_price"] = round(price_for_value(case, terms, est, target), 2)
        if not must_haves_ok(case, terms, std):
            continue
        rows.append((cost(case, terms, std, est), terms))
    if not rows:
        return None
    low = min(c for c, _ in rows)
    ties = [(c, t) for c, t in rows if c <= low + max(1.0, abs(low) * 1e-5)]
    c, terms = max(ties, key=lambda r: friendliness(r[1]))
    return terms, c


def at_price(case, terms, price):
    return {**terms, "unit_price": round(price, 2)}


def relationship_optimum(case, terms, std, est, lo, hi):
    """Relationship goals: the price in [lo, hi] with the lowest C, relationship charge included
    (C falls with price until the margin charge grows faster). Without a full-cost estimate: lo."""
    if case["buyer"].get("category_goal") not in RELATIONSHIP_GOALS or not est.get("full_cost"):
        return None
    best_p, best_c = lo, math.inf
    steps = 200
    for i in range(steps + 1):
        p = lo + (hi - lo) * i / steps
        c = cost(case, at_price(case, terms, p), std, est)
        if c < best_c - 1e-6:
            best_p, best_c = p, c
    return round(best_p, 2)
"""Data arguments, each one sentence with its figure next to its IDs, computed the way the arena
checks them (`docs/api.md`, What counts). Only arguments that push the price our way are kept;
a rising index or a should-cost above the quote would argue the supplier's case.

In the sandbox the case's refs point into a demo world our package does not hold: those are cited
without a figure, so the arena checks them against their own value."""

import re

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")
SERIES_NAME = {
    "PPI-C2451": "Producer prices for iron castings",
    "PPI-C2452": "Producer prices for steel castings",
    "PPI-C2562": "Producer prices for machining",
    "PPI-C2594": "Producer prices for fasteners",
    "PPI-C2711": "Producer prices for electric motors",
    "PPI-C2611": "Producer prices for electronic components",
    "PPI-C2815": "Producer prices for bearings and gears",
    "PPI-C241": "Producer prices for basic iron and steel",
    "PPI-C2431": "Producer prices for cold-drawn bars",
    "PPI-C2219": "Producer prices for rubber products",
    "PPI-D351": "Electricity producer prices",
    "PPI-D35": "Energy supply producer prices",
    "LCI-C": "Manufacturing labour costs",
    "WB-CU": "Copper",
    "WB-NI": "Nickel",
    "WB-AL": "Aluminium",
    "WB-NGEU": "European natural gas",
    "CU-NOTATION": "The copper notation",
    "AS-14404": "The 1.4404 alloy surcharge",
    "AS-14301": "The 1.4301 alloy surcharge",
}


def months_back(month, n):
    y, m = (int(x) for x in month.split("-"))
    m -= n
    while m <= 0:
        m, y = m + 12, y - 1
    return f"{y}-{m:02d}"


def money(x):
    return f"EUR {x:.2f}"


def per_unit(fact):
    """Pieces a recorded price covers: 15 of 108 quotes and some orders are priced per 100 or 1000."""
    try:
        return int(fact.get("price_unit") or 1) or 1
    except (TypeError, ValueError):
        return 1


class ClaimBank:
    """Arguments for one case. `pkg` is the data package (or None); the case's own `facts` win."""

    def __init__(self, pkg, case):
        self.pkg, self.case = pkg, case
        self.facts = case.get("facts") or {}
        self.refs = list(case.get("refs") or [])
        # a case whose refs the package does not know (the sandbox's demo world)
        self.foreign = bool(self.refs) and pkg is not None and not any(pkg.lookup(r) for r in self.refs)

    def fact(self, ref):
        if ref in self.facts:
            return self.facts[ref]
        return None if self.foreign or self.pkg is None else self.pkg.lookup(ref)

    def ids(self, prefix):
        out = set() if self.foreign or self.pkg is None else set(self.pkg.ids(prefix))
        out |= {k for k in self.facts if k.startswith(prefix)}
        out |= {r for r in self.refs if r.startswith(prefix)}
        return sorted(out)

    def query(self, sql, params=()):
        if self.foreign or self.pkg is None:
            return []
        try:
            return self.pkg.query(sql, params)
        except Exception:  # noqa: BLE001 - a package without SQLite: facts only
            return []

    # -- single arguments ------------------------------------------------------------------
    def should_cost(self, part, sid, quote):
        best = None
        for ref in self.ids("cost:"):
            f = self.fact(ref)
            if not f or f.get("part") != part or not f.get("unit_cost"):
                continue
            if ref.endswith("-" + sid.split(":")[-1]):
                best = (ref, f)
                break
            if best is None and "-" not in ref.split(":")[-1]:
                best = (ref, f)
        if not best:
            return None
        ref, f = best
        if quote and f["unit_cost"] >= quote * 0.98:
            return None  # above or near its price: argues its case
        return {
            "kind": "should_cost",
            "ids": [ref],
            "text": f"Our bottom-up should-cost estimate for this part is {money(f['unit_cost'])} per unit ({ref}).",
            "strength": 5,
        }

    def order_history(self, part, sid, quote):
        rows = self.query(
            "SELECT id FROM po_lines WHERE part_id = ? AND supplier_id = ? ORDER BY order_date DESC LIMIT 3",
            (part, sid),
        )
        facts = [(r["id"], self.fact(r["id"])) for r in rows]
        facts = [(i, f) for i, f in facts if f and f.get("unit_price")]
        if len(facts) < 2:
            return None
        prices = [f["unit_price"] for _, f in facts]
        unit = per_unit(facts[0][1])
        if quote and min(prices) / unit >= quote:
            return None  # the figure stays as recorded (per 100 or 1000 where priced so): that is what is checked
        ids = [i for i, _ in facts]
        each = f" per {unit} units" if unit != 1 else ""
        if len(set(prices)) == 1:
            text = f"Our last {len(ids)} orders for this part were at {money(prices[0])}{each} ({', '.join(ids)})."
        else:
            listed = " and ".join(money(p) for p in prices)
            text = f"Our last orders for this part were at {listed}{each} ({', '.join(ids)})."
        return {"kind": "order_history", "ids": ids, "text": text, "strength": 4}

    def notice(self, sid):
        doc = self.case.get("trigger_doc")
        f = self.fact(doc) if doc else None
        if not f or f.get("days") is None:
            return None
        ctr = next((r for r in self.refs if r.startswith("ctr:") and "#" not in r), None)
        c = self.fact(ctr) if ctr else None
        if not c or c.get("days") is None or f["days"] >= c["days"]:
            return None
        text = (
            f"Your letter gives {f['days']} days' notice ({doc}); our agreement provides for {c['days']} days ({ctr})."
        )
        return {"kind": "notice", "ids": [doc, ctr], "text": text, "strength": 5}

    def move12(self, series):
        """The series' change over the last twelve months as a share (what suppliers cite), or None."""
        ids = self.ids(f"idx:{series}@")
        if not ids:
            return None
        m2 = ids[-1].split("@")[-1]
        a, b = self.fact(f"idx:{series}@{months_back(m2, 12)}"), self.fact(ids[-1])
        if not a or not b or not a.get("value") or not b.get("value"):
            return None
        return b["value"] / a["value"] - 1

    def index_change(self, series):
        """The largest fall of a series over any window of up to 12 months ending at its latest
        month (the window the arena checks). AS-14404 rose 5.9 % in twelve months but fell 5.5 %
        from June to September 2026: the second is the argument the distributors "take into
        account", the first would argue their case."""
        ids = self.ids(f"idx:{series}@")
        if not ids:
            return None
        m2 = ids[-1].split("@")[-1]
        b = self.fact(ids[-1])
        if not b or not b.get("value"):
            return None
        best = None
        for back in range(1, 13):
            m1 = months_back(m2, back)
            a = self.fact(f"idx:{series}@{m1}")
            if not a or not a.get("value"):
                continue
            pct = (b["value"] / a["value"] - 1) * 100
            if best is None or pct < best[0]:
                best = (pct, m1)
        if best is None or best[0] > -0.5:
            return None  # a rising driver confirms the supplier's case
        pct, m1 = best
        name = SERIES_NAME.get(series, f"The index {series}")
        return {
            "kind": "index",
            "ids": [f"idx:{series}@{m1}", f"idx:{series}@{m2}"],
            "text": f"{name} changed {pct:.1f}% from {m1} to {m2} (idx:{series}@{m1}, idx:{series}@{m2}).",
            "strength": 4 + min(3.0, abs(pct) / 2),  # a falling driver outranks notes and orders
        }

    def drivers(self, part):
        return [r["series_id"] for r in self.query("SELECT series_id FROM cost_drivers WHERE part_id = ?", (part,))]

    def forecast(self, part):
        ids = self.ids(f"fc:{part.split(':')[-1]}@")
        f = self.fact(ids[-1]) if ids else None
        if not f or (f.get("change_pct") or 0) <= 0:
            return None
        text = f"Our forecast for this part is up {f['change_pct']:.1f}% ({ids[-1]})."
        return {"kind": "forecast", "ids": [ids[-1]], "text": text, "strength": 2}

    def rival_quote(self, part, sid, price):
        """A quote of this case from another supplier, cheaper than this supplier's price."""
        out = []
        for ref in self.refs:
            f = self.fact(ref) if ref.startswith("quote:") else None
            if not f or f.get("part") != part or f.get("supplier") == sid or not price or not f.get("unit_price"):
                continue
            unit = per_unit(f)
            if f["unit_price"] / unit < price:
                each = f"per {unit} units" if unit != 1 else "per unit"
                out.append(
                    {
                        "kind": "rival",
                        "ids": [ref],
                        "text": f"We hold another quote for this part at {money(f['unit_price'])} {each} ({ref}).",
                        "strength": 6,
                        "rival": True,
                    }
                )
        return out

    def signal_notes(self, sid):
        """Its own words in our notes that weaken its case: material bought forward at fixed prices,
        an offer to open its calculation. Context for the person reading, not a checked figure."""
        out = []
        for d in self.query(
            "SELECT id, date, kind, file FROM documents WHERE supplier_id = ? ORDER BY date DESC", (sid,)
        ):
            path = self.pkg.root / (d.get("file") or "") if self.pkg else None
            text = path.read_text(encoding="utf-8", errors="replace") if path and path.is_file() else ""
            if re.search(r"covered at fixed prices|bought their \w+ forward|material covered until", text, re.I):
                out.append(
                    {
                        "kind": "hedged",
                        "ids": [d["id"]],
                        "text": f"Your letter of {d['date']} ({d['id']}) says your material is covered at fixed "
                        "prices, so recent index movements do not reach your costs yet.",
                        "strength": 5,
                    }
                )
            if re.search(r"walk us through their calculation", text, re.I):
                out.append(
                    {
                        "kind": "open_book",
                        "ids": [d["id"]],
                        "text": f"In our call of {d['date']} ({d['id']}) you offered to walk us through your "
                        "calculation; we would welcome that now.",
                        "strength": 4,
                    }
                )
        seen, uniq = set(), []
        for c in out:
            if c["kind"] not in seen:
                seen.add(c["kind"])
                uniq.append(c)
        return uniq

    def scorecard(self, sid, quality):
        ids = self.ids(f"sc:{sid.split(':')[-1]}@")
        if not ids:
            return None
        f = self.fact(ids[-1])
        if f is None:  # demo world: cite without a figure
            text = f"We have reviewed your delivery performance in our supplier scorecard ({ids[-1]})."
            return {"kind": "scorecard", "ids": [ids[-1]], "text": text, "strength": 2}
        quarter = f.get("quarter") or ids[-1].split("@")[-1]
        if quality:
            if (f.get("ppm") or 0) < 1000:
                return None
            text = f"Your deliveries ran at {f['ppm']} ppm in {quarter} ({ids[-1]})."
        else:
            if (f.get("otd_pct") or 100) >= 90:
                return None
            text = f"Your on-time delivery was {f['otd_pct']}% in {quarter} ({ids[-1]})."
        return {"kind": "scorecard", "ids": [ids[-1]], "text": text, "strength": 2}

    def demo_refs(self):
        """Refs the package cannot resolve: cited without a figure."""
        words = {
            "cost": ("should_cost", "Our bottom-up should-cost estimate for this part is on file ({ids}).", 5),
            "po": ("order_history", "We compared your offer with our recent order prices for this part ({ids}).", 4),
        }
        out = []
        for kind, (name, text, strength) in words.items():
            ids = [r for r in self.refs if r.startswith(f"{kind}:") and self.fact(r) is None]
            if ids:
                out.append(
                    {"kind": name, "ids": ids[:3], "text": text.format(ids=", ".join(ids[:3])), "strength": strength}
                )
        doc = self.case.get("trigger_doc")
        ctr = next((r for r in self.refs if r.startswith("ctr:")), None)
        if doc and ctr and self.fact(doc) is None and self.case.get("type") == "price_increase":
            text = f"Your letter ({doc}) gives less notice than our agreement provides for ({ctr})."
            out.append({"kind": "notice", "ids": [doc, ctr], "text": text, "strength": 5})
        return out

    # -- per supplier ----------------------------------------------------------------------
    def for_supplier(self, sid, quote):
        """Every argument for this supplier that pushes our way, strongest first."""
        case, out = self.case, []
        quality = case.get("type") == "quality" or case["buyer"].get("category_goal") == "quality_first"
        single = len(case.get("parts") or []) == 1  # a bundle's price is not one part's order price
        for part in case.get("parts") or []:
            history = self.order_history(part, sid, quote) if single else None
            out += [c for c in (self.should_cost(part, sid, quote), history) if c]
            out += [c for c in (self.index_change(s) for s in self.drivers(part)) if c]
            out += self.rival_quote(part, sid, quote)
            if c := self.forecast(part):
                out.append(c)
        if c := self.notice(sid):
            out.append(c)
        out += self.signal_notes(sid)
        if c := self.scorecard(sid, quality):
            out.append(c)
        if self.foreign:
            out += self.demo_refs()
        seen, uniq = set(), []
        for c in sorted(out, key=lambda c: -c["strength"]):
            if tuple(c["ids"]) not in seen:
                seen.add(tuple(c["ids"]))
                uniq.append(c)
        return uniq


def rival_offer(sid, offer_id, price):
    """Another bidder's standing offer in this session, citable to the others."""
    return {
        "kind": "rival",
        "ids": [offer_id],
        "text": f"Another bidder offers {money(price)} per unit for this part ({offer_id}).",
        "strength": 7,
        "rival": True,
        "from": sid,
    }
"""What the data says about a supplier before the first move: owner type, the persona traits in
its notes, letters, quote remarks and news (the package and the Sunday release alike), and from
those its cost of money. Unknown suppliers (not in the package, e.g. the sandbox) get the neutral
profile; their own e-mails are scanned for the same traits as they arrive (`signals_in`)."""

import re

# One or two fixed phrases per trait in the generated texts, widened to the word forms seen across
# the whole package (restructuring programme, lowered its rating, "nickel and alloys forward").
SIGNALS = {
    "cash_need": r"pay earlier|bank is watching|cash and the banks|within 10 days|under pressure"
    r"|restructur\w*|short-time work|lower\w* (its |their )?rating|cash is tight|we like fast payers"
    r"|negotiat\w+ with (its|their) banks|lowers our margin|loss-making|liquidity|waiting for cash",
    "spare_capacity": r"second shift has been on hold|take additional parts|looks for new customers"
    r"|free (machine )?capacity|keep (the|our) machines (busy|running)",
    "capacity_full": r"order intake is very strong|binding 12-month commitment"
    r"|cannot confirm your full forecast|fully booked|allocat\w+ (volumes|in line)|factory is super busy"
    r"|high capacity utili[sz]ation|prioriti[sz]e customers with firm",
    "open_book": r"walk (us|you) through (their|our) calculation",
    "stale_costing": r"not followed (his|its|their) material|own spreadsheet",
    "partnership_2022": r"kept supplying at the old price",
    "reference_customer": r"important reference customer",
    "approval_2pct": r"above 2 ?% need the approval|pricing committee",
    "deprioritising_us": r"reviewing small accounts|not strategic|reorganising our range"
    r"|supply from stock only|sharpens its focus|focus on customers with volume",
    "price_frozen": r"no room on price|not discounted|price list applies to all|discounts not possible"
    r"|frozen all price reductions",
    "hedged": r"bought (their|our) [\w ,]{1,40} forward|covered at fixed prices|material covered until"
    r"|secures power prices|hedged",
    "complains_late_pay": r"invoices are overdue",
}
# Cost of money per year by owner type (seen in practice: groups 4 to 7 %, family firms 7 to 8.5 %,
# founder-run job shops 12 to 17 %); a cash need adds to it.
RATE = {"group": 0.05, "private": 0.07, "family": 0.075, "founder": 0.12}
DEFAULT_RATE = 0.07


def signals_in(text):
    return sorted(k for k, pat in SIGNALS.items() if re.search(pat, text or "", re.I))


def supplier_texts(pkg, sid):
    """Every text about this supplier: its letters, call and meeting notes and news, from the
    package and the Sunday release (both reach `ids` and `document`), plus its quote remarks."""
    texts = []
    for ref in pkg.ids("doc:") + pkg.ids("news:"):
        row = pkg.lookup(ref) or {}
        if row.get("supplier") != sid and row.get("supplier_id") != sid:
            continue
        try:
            texts.append(pkg.document(ref))
        except Exception:  # noqa: BLE001 - a row without a readable file: its headline still counts
            texts.append(" ".join(str(v) for k, v in row.items() if k in ("title", "headline", "body", "subject")))
    try:
        texts += [r.get("remarks") or "" for r in pkg.query("SELECT remarks FROM quotes WHERE supplier_id = ?", (sid,))]
    except Exception:  # noqa: BLE001 - no SQLite
        pass
    return texts


def profile(pkg, sid):
    """{owner_type, country, category, signals, rate, warm}; neutral when the package does not know it."""
    out = {"owner_type": None, "country": None, "category": None, "signals": [], "rate": DEFAULT_RATE, "warm": True}
    if pkg is None or not pkg.lookup(sid):
        return out
    try:
        sup = pkg.query("SELECT country, category, skonto_days, skonto_pct FROM suppliers WHERE id = ?", (sid,))
        intel = pkg.query("SELECT owner_type, staff FROM supplier_intel WHERE supplier_id = ?", (sid,))
    except Exception:  # noqa: BLE001 - no SQLite: neutral
        return out
    sig = signals_in("\n".join(supplier_texts(pkg, sid)))
    owner = intel[0]["owner_type"] if intel else None
    rate = RATE.get(owner, DEFAULT_RATE)
    if "cash_need" in sig:
        rate += 0.05
    if sup and sup[0].get("skonto_pct") and sup[0].get("skonto_days"):
        # a cash discount of s % for paying d days early is worth s / d * 360 % a year to it
        days_early = max(1, 30 - int(sup[0]["skonto_days"]))
        rate = max(rate, min(0.2, sup[0]["skonto_pct"] / 100 * 360 / max(days_early, 10) / 2))
    out.update(
        owner_type=owner,
        country=sup[0]["country"] if sup else None,
        category=sup[0]["category"] if sup else None,
        signals=sig,
        rate=round(rate, 3),
        warm=owner in (None, "family", "founder", "private"),
    )
    return out

toolUseResult.stdout:
"""Numbers only: C of a sheet, what a sheet is worth to the supplier, the non-price terms we ask for
and, in relationship goals, the price below which a lower price costs us more than it saves.
Nothing here calls a model; every figure that reaches a term sheet comes from here."""

import itertools
import math

from arena_kit.cost import closing_terms, complete_offer, must_haves_ok, supplier_value, total_cost

RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}


def cost(case, terms, std=None, est=None):
    """C in EUR; infinite for sheets the cost function cannot price. The relationship charge
    needs a full-cost estimate; without one it counts as 0."""
    if est is not None and not est.get("full_cost"):
        est = None
    try:
        return total_cost(case, terms, std, est)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        return math.inf


def c_alt(case):
    alt = case["buyer"].get("alternative") or {}
    terms = alt.get("terms") or {}
    if alt.get("kind") in (None, "none") or not terms.get("unit_price"):
        return math.inf
    return cost(case, terms)


def deal_cost(case, terms, std, est=None):
    """The accept gate: C of a sheet with a price that keeps every must-have and is cheaper than
    the alternative (relationship charge included), else None. The C returned is the C checked."""
    if not terms.get("unit_price") or not must_haves_ok(case, terms, std):
        return None
    c = cost(case, terms, std, est)
    return c if c < c_alt(case) else None


def known_incoterm(case, terms):
    """`terms` with an Incoterm the case prices; an unknown one (a hidden case's quote) would be a
    KeyError in the kit, so it falls back to the costliest, as `closing_terms` does for a gap."""
    freight = case["buyer"]["freight_eur_per_unit"]
    if terms.get("incoterm") in freight or "incoterm" not in terms:
        return terms
    return {**terms, "incoterm": max(freight, key=freight.get)}


def estimate(case, std, rate, full_cost=None, ppm=None, lead=None, overtime=0.0):
    """Our view of the supplier for `supplier_value` and the relationship term. `lead`: the lead
    time it quoted; `overtime`: what each day faster costs it, as a share of the price."""
    standard = known_incoterm(case, closing_terms(case, {}, known_incoterm(case, std or {})))
    est = {"standard": standard, "interest_rate": rate, "lead": lead, "overtime": overtime}
    if ppm is not None:
        est["ppm"] = ppm
    if full_cost:
        est["full_cost"] = full_cost
    est["index_moves"] = {}  # series -> its change over the last 12 months (share), what the supplier expects on
    return est


def clause_value(case, terms, est):
    """What an index clause is worth to the supplier per unit: it expects its driver to move on as
    it did over the last twelve months (what it cites in its quote), and the clause pays it that
    share beyond the deadband. Nordmark agreed at once to a copper clause 4 % below its fixed
    price (P02); the distributors priced the AS-14404 deadband at exactly this (P08, P18)."""
    clause = terms.get("index_clause")
    if not clause:
        return 0.0
    move = est.get("index_moves", {}).get(clause.get("series"))
    if move is None:
        return 0.0
    exposed = max(0.0, move - (clause.get("deadband_pct") or 0) / 100)
    return (clause.get("material_share") or 0) * exposed * (terms.get("unit_price") or 0)


def clause_cost_share(case, clause):
    """Our cost of a clause as a share of the spend: the case's path beyond the deadband plus the
    index risk charge."""
    b = case["buyer"]
    share, deadband = clause.get("material_share") or 0, (clause.get("deadband_pct") or 0) / 100
    path = abs(b.get("index_paths", {}).get(clause.get("series"), 0.0))
    return share * max(0.0, path - deadband) + share * b.get("index_risk_pct", 0) / 100


def clause_trade(case, est, min_gain=0.02):
    """The index clause worth trading: the supplier's value less our cost, as a share of the price,
    above `min_gain`; among equal gains the widest deadband (least risk). None when no clause pays
    (P08, P18: the supplier's value equals our cost) or the case has none to offer."""
    best = None
    for clause in case.get("term_options", {}).get("index_clause") or []:
        if not clause:
            continue
        move = est.get("index_moves", {}).get(clause.get("series"))
        if move is None:
            continue
        theirs = (clause.get("material_share") or 0) * max(0.0, move - (clause.get("deadband_pct") or 0) / 100)
        gain = theirs - clause_cost_share(case, clause)
        key = (round(gain, 4), clause.get("deadband_pct") or 0)
        if gain >= min_gain and (best is None or key > best[0]):
            best = (key, clause)
    return best[1] if best else None


def value(case, terms, est):
    """What a sheet is worth to the supplier per unit, in cash at its standard terms, less the
    overtime a faster delivery than it quoted costs it (fully booked suppliers: about 0.5 % of
    the price per day, P05 and P10)."""
    v = supplier_value(case, known_incoterm(case, terms), est) + clause_value(case, terms, est)
    lead, quoted = terms.get("lead_time_days"), est.get("lead")
    if est.get("overtime") and lead is not None and quoted and lead < quoted:
        v -= est["overtime"] * terms["unit_price"] * (quoted - lead)
    return v


def price_for_value(case, terms, est, target):
    """The unit price at which `terms` are worth `target` to the supplier (value rises with price)."""
    lo, hi = 0.0, max(1.0, target) * 3
    for _ in range(60):
        mid = (lo + hi) / 2
        if value(case, {**terms, "unit_price": mid}, est) < target:
            lo = mid
        else:
            hi = mid
    return hi


def options(case):
    """Every combination of allowed non-price values: [{field: value}]."""
    opts = case.get("term_options") or {}
    fields = [f for f in case["negotiable"] if f != "unit_price" and opts.get(f)]
    return [dict(zip(fields, combo, strict=True)) for combo in itertools.product(*(opts[f] for f in fields))]


# Where a value costs us nothing more, the side the supplier prefers: a later delivery needs no
# overtime, a longer contract and a larger volume give it security (months beyond our horizon
# cost us nothing), a looser defect commitment and a smaller chargeback cost it less.
FRIENDLY = {
    "lead_time_days": 1,
    "contract_months": 1,
    "volume_per_year": 1,
    "ppm_commitment": 1,
    "chargeback_eur_per_complaint": -1,
    "tooling_eur": 1,
}


def friendliness(terms):
    """Higher is better for the supplier."""
    return tuple(FRIENDLY[f] * (terms.get(f) or 0) for f in FRIENDLY if f in terms)


def plan_terms(case, std, est, ref_terms, ref_price):
    """The non-price terms that cost us least once the supplier prices them at its own valuation:
    for every allowed combination, the price worth the same to it as `ref_price` at `ref_terms`,
    then C at that price; among equal C, the supplier's favourite. Returns (terms with that price, C)."""
    target = value(case, {**ref_terms, "unit_price": ref_price}, est)
    rows = []
    for combo in options(case) or [{}]:
        terms = complete_offer(case, {**ref_terms, **combo, "unit_price": ref_price})
        terms["unit_price"] = round(price_for_value(case, terms, est, target), 2)
        if not must_haves_ok(case, terms, std):
            continue
        rows.append((cost(case, terms, std, est), terms))
    if not rows:
        return None
    low = min(c for c, _ in rows)
    ties = [(c, t) for c, t in rows if c <= low + max(1.0, abs(low) * 1e-5)]
    c, terms = max(ties, key=lambda r: friendliness(r[1]))
    return terms, c


def at_price(case, terms, price):
    return {**terms, "unit_price": round(price, 2)}


def relationship_optimum(case, terms, std, est, lo, hi):
    """Relationship goals: the price in [lo, hi] with the lowest C, relationship charge included
    (C falls with price until the margin charge grows faster). Without a full-cost estimate: lo."""
    if case["buyer"].get("category_goal") not in RELATIONSHIP_GOALS or not est.get("full_cost"):
        return None
    best_p, best_c = lo, math.inf
    steps = 200
    for i in range(steps + 1):
        p = lo + (hi - lo) * i / steps
        c = cost(case, at_price(case, terms, p), std, est)
        if c < best_c - 1e-6:
            best_p, best_c = p, c
    return round(best_p, 2)
"""Data arguments, each one sentence with its figure next to its IDs, computed the way the arena
checks them (`docs/api.md`, What counts). Only arguments that push the price our way are kept;
a rising index or a should-cost above the quote would argue the supplier's case.

In the sandbox the case's refs point into a demo world our package does not hold: those are cited
without a figure, so the arena checks them against their own value."""

import re

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")
SERIES_NAME = {
    "PPI-C2451": "Producer prices for iron castings",
    "PPI-C2452": "Producer prices for steel castings",
    "PPI-C2562": "Producer prices for machining",
    "PPI-C2594": "Producer prices for fasteners",
    "PPI-C2711": "Producer prices for electric motors",
    "PPI-C2611": "Producer prices for electronic components",
    "PPI-C2815": "Producer prices for bearings and gears",
    "PPI-C241": "Producer prices for basic iron and steel",
    "PPI-C2431": "Producer prices for cold-drawn bars",
    "PPI-C2219": "Producer prices for rubber products",
    "PPI-D351": "Electricity producer prices",
    "PPI-D35": "Energy supply producer prices",
    "LCI-C": "Manufacturing labour costs",
    "WB-CU": "Copper",
    "WB-NI": "Nickel",
    "WB-AL": "Aluminium",
    "WB-NGEU": "European natural gas",
    "CU-NOTATION": "The copper notation",
    "AS-14404": "The 1.4404 alloy surcharge",
    "AS-14301": "The 1.4301 alloy surcharge",
}


def months_back(month, n):
    y, m = (int(x) for x in month.split("-"))
    m -= n
    while m <= 0:
        m, y = m + 12, y - 1
    return f"{y}-{m:02d}"


def money(x):
    return f"EUR {x:.2f}"


def per_unit(fact):
    """Pieces a recorded price covers: 15 of 108 quotes and some orders are priced per 100 or 1000."""
    try:
        return int(fact.get("price_unit") or 1) or 1
    except (TypeError, ValueError):
        return 1


class ClaimBank:
    """Arguments for one case. `pkg` is the data package (or None); the case's own `facts` win."""

    def __init__(self, pkg, case):
        self.pkg, self.case = pkg, case
        self.facts = case.get("facts") or {}
        self.refs = list(case.get("refs") or [])
        # a case whose refs the package does not know (the sandbox's demo world)
        self.foreign = bool(self.refs) and pkg is not None and not any(pkg.lookup(r) for r in self.refs)

    def fact(self, ref):
        if ref in self.facts:
            return self.facts[ref]
        return None if self.foreign or self.pkg is None else self.pkg.lookup(ref)

    def ids(self, prefix):
        out = set() if self.foreign or self.pkg is None else set(self.pkg.ids(prefix))
        out |= {k for k in self.facts if k.startswith(prefix)}
        out |= {r for r in self.refs if r.startswith(prefix)}
        return sorted(out)

    def query(self, sql, params=()):
        if self.foreign or self.pkg is None:
            return []
        try:
            return self.pkg.query(sql, params)
        except Exception:  # noqa: BLE001 - a package without SQLite: facts only
            return []

    # -- single arguments ------------------------------------------------------------------
    def should_cost(self, part, sid, quote):
        best = None
        for ref in self.ids("cost:"):
            f = self.fact(ref)
            if not f or f.get("part") != part or not f.get("unit_cost"):
                continue
            if ref.endswith("-" + sid.split(":")[-1]):
                best = (ref, f)
                break
            if best is None and "-" not in ref.split(":")[-1]:
                best = (ref, f)
        if not best:
            return None
        ref, f = best
        if quote and f["unit_cost"] >= quote * 0.98:
            return None  # above or near its price: argues its case
        return {
            "kind": "should_cost",
            "ids": [ref],
            "text": f"Our bottom-up should-cost estimate for this part is {money(f['unit_cost'])} per unit ({ref}).",
            "strength": 5,
        }

    def order_history(self, part, sid, quote):
        rows = self.query(
            "SELECT id FROM po_lines WHERE part_id = ? AND supplier_id = ? ORDER BY order_date DESC LIMIT 3",
            (part, sid),
        )
        facts = [(r["id"], self.fact(r["id"])) for r in rows]
        facts = [(i, f) for i, f in facts if f and f.get("unit_price")]
        if len(facts) < 2:
            return None
        prices = [f["unit_price"] for _, f in facts]
        unit = per_unit(facts[0][1])
        if quote and min(prices) / unit >= quote:
            return None  # the figure stays as recorded (per 100 or 1000 where priced so): that is what is checked
        ids = [i for i, _ in facts]
        each = f" per {unit} units" if unit != 1 else ""
        if len(set(prices)) == 1:
            text = f"Our last {len(ids)} orders for this part were at {money(prices[0])}{each} ({', '.join(ids)})."
        else:
            listed = " and ".join(money(p) for p in prices)
            text = f"Our last orders for this part were at {listed}{each} ({', '.join(ids)})."
        return {"kind": "order_history", "ids": ids, "text": text, "strength": 4}

    def notice(self, sid):
        doc = self.case.get("trigger_doc")
        f = self.fact(doc) if doc else None
        if not f or f.get("days") is None:
            return None
        ctr = next((r for r in self.refs if r.startswith("ctr:") and "#" not in r), None)
        c = self.fact(ctr) if ctr else None
        if not c or c.get("days") is None or f["days"] >= c["days"]:
            return None
        text = (
            f"Your letter gives {f['days']} days' notice ({doc}); our agreement provides for {c['days']} days ({ctr})."
        )
        return {"kind": "notice", "ids": [doc, ctr], "text": text, "strength": 5}

    def move12(self, series):
        """The series' change over the last twelve months as a share (what suppliers cite), or None."""
        ids = self.ids(f"idx:{series}@")
        if not ids:
            return None
        m2 = ids[-1].split("@")[-1]
        a, b = self.fact(f"idx:{series}@{months_back(m2, 12)}"), self.fact(ids[-1])
        if not a or not b or not a.get("value") or not b.get("value"):
            return None
        return b["value"] / a["value"] - 1

    def index_change(self, series):
        """The largest fall of a series over any window of up to 12 months ending at its latest
        month (the window the arena checks). AS-14404 rose 5.9 % in twelve months but fell 5.5 %
        from June to September 2026: the second is the argument the distributors "take into
        account", the first would argue their case."""
        ids = self.ids(f"idx:{series}@")
        if not ids:
            return None
        m2 = ids[-1].split("@")[-1]
        b = self.fact(ids[-1])
        if not b or not b.get("value"):
            return None
        best = None
        for back in range(1, 13):
            m1 = months_back(m2, back)
            a = self.fact(f"idx:{series}@{m1}")
            if not a or not a.get("value"):
                continue
            pct = (b["value"] / a["value"] - 1) * 100
            if best is None or pct < best[0]:
                best = (pct, m1)
        if best is None or best[0] > -0.5:
            return None  # a rising driver confirms the supplier's case
        pct, m1 = best
        name = SERIES_NAME.get(series, f"The index {series}")
        return {
            "kind": "index",
            "ids": [f"idx:{series}@{m1}", f"idx:{series}@{m2}"],
            "text": f"{name} changed {pct:.1f}% from {m1} to {m2} (idx:{series}@{m1}, idx:{series}@{m2}).",
            "strength": 4 + min(3.0, abs(pct) / 2),  # a falling driver outranks notes and orders
        }

    def drivers(self, part):
        return [r["series_id"] for r in self.query("SELECT series_id FROM cost_drivers WHERE part_id = ?", (part,))]

    def forecast(self, part):
        ids = self.ids(f"fc:{part.split(':')[-1]}@")
        f = self.fact(ids[-1]) if ids else None
        if not f or (f.get("change_pct") or 0) <= 0:
            return None
        text = f"Our forecast for this part is up {f['change_pct']:.1f}% ({ids[-1]})."
        return {"kind": "forecast", "ids": [ids[-1]], "text": text, "strength": 2}

    def rival_quote(self, part, sid, price):
        """A quote of this case from another supplier, cheaper than this supplier's price."""
        out = []
        for ref in self.refs:
            f = self.fact(ref) if ref.startswith("quote:") else None
            if not f or f.get("part") != part or f.get("supplier") == sid or not price or not f.get("unit_price"):
                continue
            unit = per_unit(f)
            if f["unit_price"] / unit < price:
                each = f"per {unit} units" if unit != 1 else "per unit"
                out.append(
                    {
                        "kind": "rival",
                        "ids": [ref],
                        "text": f"We hold another quote for this part at {money(f['unit_price'])} {each} ({ref}).",
                        "strength": 6,
                        "rival": True,
                    }
                )
        return out

    def signal_notes(self, sid):
        """Its own words in our notes that weaken its case: material bought forward at fixed prices,
        an offer to open its calculation. Context for the person reading, not a checked figure."""
        out = []
        for d in self.query(
            "SELECT id, date, kind, file FROM documents WHERE supplier_id = ? ORDER BY date DESC", (sid,)
        ):
            path = self.pkg.root / (d.get("file") or "") if self.pkg else None
            text = path.read_text(encoding="utf-8", errors="replace") if path and path.is_file() else ""
            if re.search(r"covered at fixed prices|bought their \w+ forward|material covered until", text, re.I):
                out.append(
                    {
                        "kind": "hedged",
                        "ids": [d["id"]],
                        "text": f"Your letter of {d['date']} ({d['id']}) says your material is covered at fixed "
                        "prices, so recent index movements do not reach your costs yet.",
                        "strength": 5,
                    }
                )
            if re.search(r"walk us through their calculation", text, re.I):
                out.append(
                    {
                        "kind": "open_book",
                        "ids": [d["id"]],
                        "text": f"In our call of {d['date']} ({d['id']}) you offered to walk us through your "
                        "calculation; we would welcome that now.",
                        "strength": 4,
                    }
                )
        seen, uniq = set(), []
        for c in out:
            if c["kind"] not in seen:
                seen.add(c["kind"])
                uniq.append(c)
        return uniq

    def scorecard(self, sid, quality):
        ids = self.ids(f"sc:{sid.split(':')[-1]}@")
        if not ids:
            return None
        f = self.fact(ids[-1])
        if f is None:  # demo world: cite without a figure
            text = f"We have reviewed your delivery performance in our supplier scorecard ({ids[-1]})."
            return {"kind": "scorecard", "ids": [ids[-1]], "text": text, "strength": 2}
        quarter = f.get("quarter") or ids[-1].split("@")[-1]
        if quality:
            if (f.get("ppm") or 0) < 1000:
                return None
            text = f"Your deliveries ran at {f['ppm']} ppm in {quarter} ({ids[-1]})."
        else:
            if (f.get("otd_pct") or 100) >= 90:
                return None
            text = f"Your on-time delivery was {f['otd_pct']}% in {quarter} ({ids[-1]})."
        return {"kind": "scorecard", "ids": [ids[-1]], "text": text, "strength": 2}

    def demo_refs(self):
        """Refs the package cannot resolve: cited without a figure."""
        words = {
            "cost": ("should_cost", "Our bottom-up should-cost estimate for this part is on file ({ids}).", 5),
            "po": ("order_history", "We compared your offer with our recent order prices for this part ({ids}).", 4),
        }
        out = []
        for kind, (name, text, strength) in words.items():
            ids = [r for r in self.refs if r.startswith(f"{kind}:") and self.fact(r) is None]
            if ids:
                out.append(
                    {"kind": name, "ids": ids[:3], "text": text.format(ids=", ".join(ids[:3])), "strength": strength}
                )
        doc = self.case.get("trigger_doc")
        ctr = next((r for r in self.refs if r.startswith("ctr:")), None)
        if doc and ctr and self.fact(doc) is None and self.case.get("type") == "price_increase":
            text = f"Your letter ({doc}) gives less notice than our agreement provides for ({ctr})."
            out.append({"kind": "notice", "ids": [doc, ctr], "text": text, "strength": 5})
        return out

    # -- per supplier ----------------------------------------------------------------------
    def for_supplier(self, sid, quote):
        """Every argument for this supplier that pushes our way, strongest first."""
        case, out = self.case, []
        quality = case.get("type") == "quality" or case["buyer"].get("category_goal") == "quality_first"
        single = len(case.get("parts") or []) == 1  # a bundle's price is not one part's order price
        for part in case.get("parts") or []:
            history = self.order_history(part, sid, quote) if single else None
            out += [c for c in (self.should_cost(part, sid, quote), history) if c]
            out += [c for c in (self.index_change(s) for s in self.drivers(part)) if c]
            out += self.rival_quote(part, sid, quote)
            if c := self.forecast(part):
                out.append(c)
        if c := self.notice(sid):
            out.append(c)
        out += self.signal_notes(sid)
        if c := self.scorecard(sid, quality):
            out.append(c)
        if self.foreign:
            out += self.demo_refs()
        seen, uniq = set(), []
        for c in sorted(out, key=lambda c: -c["strength"]):
            if tuple(c["ids"]) not in seen:
                seen.add(tuple(c["ids"]))
                uniq.append(c)
        return uniq


def rival_offer(sid, offer_id, price):
    """Another bidder's standing offer in this session, citable to the others."""
    return {
        "kind": "rival",
        "ids": [offer_id],
        "text": f"Another bidder offers {money(price)} per unit for this part ({offer_id}).",
        "strength": 7,
        "rival": True,
        "from": sid,
    }
"""What the data says about a supplier before the first move: owner type, the persona traits in
its notes, letters, quote remarks and news (the package and the Sunday release alike), and from
those its cost of money. Unknown suppliers (not in the package, e.g. the sandbox) get the neutral
profile; their own e-mails are scanned for the same traits as they arrive (`signals_in`)."""

import re

# One or two fixed phrases per trait in the generated texts, widened to the word forms seen across
# the whole package (restructuring programme, lowered its rating, "nickel and alloys forward").
SIGNALS = {
    "cash_need": r"pay earlier|bank is watching|cash and the banks|within 10 days|under pressure"
    r"|restructur\w*|short-time work|lower\w* (its |their )?rating|cash is tight|we like fast payers"
    r"|negotiat\w+ with (its|their) banks|lowers our margin|loss-making|liquidity|waiting for cash",
    "spare_capacity": r"second shift has been on hold|take additional parts|looks for new customers"
    r"|free (machine )?capacity|keep (the|our) machines (busy|running)",
    "capacity_full": r"order intake is very strong|binding 12-month commitment"
    r"|cannot confirm your full forecast|fully booked|allocat\w+ (volumes|in line)|factory is super busy"
    r"|high capacity utili[sz]ation|prioriti[sz]e customers with firm",
    "open_book": r"walk (us|you) through (their|our) calculation",
    "stale_costing": r"not followed (his|its|their) material|own spreadsheet",
    "partnership_2022": r"kept supplying at the old price",
    "reference_customer": r"important reference customer",
    "approval_2pct": r"above 2 ?% need the approval|pricing committee",
    "deprioritising_us": r"reviewing small accounts|not strategic|reorganising our range"
    r"|supply from stock only|sharpens its focus|focus on customers with volume",
    "price_frozen": r"no room on price|not discounted|price list applies to all|discounts not possible"
    r"|frozen all price reductions",
    "hedged": r"bought (their|our) [\w ,]{1,40} forward|covered at fixed prices|material covered until"
    r"|secures power prices|hedged",
    "complains_late_pay": r"invoices are overdue",
}
# Cost of money per year by owner type (seen in practice: groups 4 to 7 %, family firms 7 to 8.5 %,
# founder-run job shops 12 to 17 %); a cash need adds to it.
RATE = {"group": 0.05, "private": 0.07, "family": 0.075, "founder": 0.12}
DEFAULT_RATE = 0.07


def signals_in(text):
    return sorted(k for k, pat in SIGNALS.items() if re.search(pat, text or "", re.I))


def supplier_texts(pkg, sid):
    """Every text about this supplier: its letters, call and meeting notes and news, from the
    package and the Sunday release (both reach `ids` and `document`), plus its quote remarks."""
    texts = []
    for ref in pkg.ids("doc:") + pkg.ids("news:"):
        row = pkg.lookup(ref) or {}
        if row.get("supplier") != sid and row.get("supplier_id") != sid:
            continue
        try:
            texts.append(pkg.document(ref))
        except Exception:  # noqa: BLE001 - a row without a readable file: its headline still counts
            texts.append(" ".join(str(v) for k, v in row.items() if k in ("title", "headline", "body", "subject")))
    try:
        texts += [r.get("remarks") or "" for r in pkg.query("SELECT remarks FROM quotes WHERE supplier_id = ?", (sid,))]
    except Exception:  # noqa: BLE001 - no SQLite
        pass
    return texts


def profile(pkg, sid):
    """{owner_type, country, category, signals, rate, warm}; neutral when the package does not know it."""
    out = {"owner_type": None, "country": None, "category": None, "signals": [], "rate": DEFAULT_RATE, "warm": True}
    if pkg is None or not pkg.lookup(sid):
        return out
    try:
        sup = pkg.query("SELECT country, category, skonto_days, skonto_pct FROM suppliers WHERE id = ?", (sid,))
        intel = pkg.query("SELECT owner_type, staff FROM supplier_intel WHERE supplier_id = ?", (sid,))
    except Exception:  # noqa: BLE001 - no SQLite: neutral
        return out
    sig = signals_in("\n".join(supplier_texts(pkg, sid)))
    owner = intel[0]["owner_type"] if intel else None
    rate = RATE.get(owner, DEFAULT_RATE)
    if "cash_need" in sig:
        rate += 0.05
    if sup and sup[0].get("skonto_pct") and sup[0].get("skonto_days"):
        # a cash discount of s % for paying d days early is worth s / d * 360 % a year to it
        days_early = max(1, 30 - int(sup[0]["skonto_days"]))
        rate = max(rate, min(0.2, sup[0]["skonto_pct"] / 100 * 360 / max(days_early, 10) / 2))
    out.update(
        owner_type=owner,
        country=sup[0]["country"] if sup else None,
        category=sup[0]["category"] if sup else None,
        signals=sig,
        rate=round(rate, 3),
        warm=owner in (None, "family", "founder", "private"),
    )
    return out

