import json, glob
# P11 sessions: which (ppm, chargeback, price) did we send and what did Kalwisz answer
for p in sorted(glob.glob("logs/sessions/practice/P11_*/*.json*"))[:0]: pass
import os
for d in sorted(glob.glob("logs/sessions/practice/P11_*")):
    for f in os.listdir(d):
        if f.endswith(".json"):
            try: data=json.load(open(os.path.join(d,f)))
            except Exception: continue
            msgs = data.get("messages") or data.get("thread") or []
            if not isinstance(msgs, list): continue
            rows=[]
