input.command:
head -c 1500 exports/README.md; echo; uv run python - <<'EOF'
import json
rows=[json.loads(l) for l in open("exports/messages.jsonl")]
p11=[r for r in rows if r.get("case_id")=="case:P11" or "P11" in str(r.get("case",""))]
print(len(rows), len(p11), list(rows[0].keys()))
import collections
seen=collections.Counter()
for r in p11:
    for sh in r.get("term_sheets") or []:
        t=sh.get("terms",{}) if isinstance(sh,dict) else {}
        seen[(r.get("from"), t.get("ppm_commitment"), t.get("chargeback_eur_per_complaint"))]+=1
for k,v in sorted(seen.items(), key=lambda x:-x[1])[:15]: print(k,v)
for r in p11:
    b=r.get("body","") or ""
    if "chargeback" in b.lower() and r.get("from")=="supplier": print("--", b[:500].replace("\n"," ")); break
EOF

